constexpr int power(int b, int e) {
    if (e == 0) return 1;
    return b * power(b, e - 1);
}

constexpr int val_ct = power(3, 4); // Compile-time calc

int dynamic_input = 5;
int val_rt = power(2, dynamic_input); // Runtime calc

class Vector2 {
public:
    const int x, y;
    constexpr Vector2(int a, int b) : x(a), y(b) {}
    constexpr int magnitude_sq() const { return x*x + y*y; }
};

constexpr Vector2 V(3, 4);
constexpr int M_SQ = V.magnitude_sq(); // CTE initialization
